const int MAX_V = 10000;

unsigned char prime[MAX_V + 1] = {0}; // Initialize directly

void sieve() {
    for (int i = 2; i <= MAX_V; i++) {
        prime[i] = 1; // Set all to 1 (true) for prime
    }
    prime[0] = prime[1] = 0; // 0 and 1 are not prime numbers
    for (int i = 2; i * i <= MAX_V; i++) {
        if (prime[i]) {
            for (int k = i * i; k <= MAX_V; k += i) {
                prime[k] = 0; 
            }
        }
    }
}

int main() {
    sieve(); // Precompute primes
    int n;
    while (scanf("%d", &n) && n) {
        int p1 = 0, q1 = 0;
        for (int i = n; i >= 3; i--) {
            if (prime[i] && prime[i - 2]) {
                q1 = i;
                p1 = i - 2;
                break;
            }
        }
        if (p1 && q1) {
            printf("%d %d\n", p1, q1);
        }
    }
    return 0;
}
